	w0 := ws.weights[0]
	w1 := ws.weights[1]
	if len(ws.weights) >= 2 {
		if inputLen < 96 {
			w0, w1 = 0.03, 0.97
		} else if inputLen < 256 {
			w0, w1 = 0.25, 0.75
		} else {
			w0, w1 = 0.55, 0.45
		}
		if req.SLOClass == "realtime" {
			w0 *= 0.4
			w1 *= 1.5
		} else if req.SLOClass == "batch" {
			w0 *= 1.2
			w1 *= 0.85
		}
		if req.SessionID != "" && inputLen >= 128 {
			w0, w1 = 0.87, 0.13
		}
		t := w0 + w1
		if t > 0 { w0 /= t; w1 /= t }
	}
