	if maxPrefix < 0.05 {
		w0, w1 = 0.0, 1.0
	}
	scores := make(map[string]float64, len(snapshots))
	// Apply prefix scores with adjusted weight
	for _, snap := range snapshots {
		s := prefixScores[snap.ID]
		if s < 0 { s = 0 }
		if s > 1 { s = 1 }
		scores[snap.ID] += s * w0
	}
	// Apply remaining scorers
	for i := 1; i < len(ws.scorers); i++ {
		dimScores := ws.scorers[i](req, snapshots)
		w := w1
		if i >= 2 { w = ws.weights[i] }
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 { s = 0 }
			if s > 1 { s = 1 }
			scores[snap.ID] += s * w
		}
	}
	minLoad, maxLoadVal, totalLoad := snapshots[0].EffectiveLoad(), snapshots[0].EffectiveLoad(), 0
	for _, snap := range snapshots {
