		if req.SessionID != "" && loadSpread <= 2.0 && snap.CacheHitRate > 0.05 {
			scores[snap.ID] += 0.025 * snap.CacheHitRate
		}
	}
	bestScore := -1e9
	bestIdx := 0
	for i, snap := range snapshots {
